html:
{#- ============================================================
    قيد يومية – Journal Entry (ERPNext)
    - عربي / إنجليزي تلقائياً حسب لغة النظام أو لغة الطباعة المختارة
    - لا يظهر إلا الحقول / الأعمدة / الأقسام التي بها قيم
   ============================================================ -#}

{#- ---------------- تحديد اللغة ---------------- -#}
{#- أولاً من ترجمة النظام الحالية (تتبع لغة الطباعة المختارة)، وإلا من frappe.lang -#}
{%- set _probe = _("Debit") | string -%}
{%- if _probe != "Debit" and _probe | length > 0 -%}
    {%- set is_ar = "\u0600" <= _probe[0] <= "\u06FF" -%}
{%- else -%}
    {%- set is_ar = ((frappe.lang or "en") | string | lower).startswith("ar") -%}
{%- endif -%}
{%- set L = 0 if is_ar else 1 -%}
{%- set dir   = "rtl" if is_ar else "ltr" -%}
{%- set start = "right" if is_ar else "left" -%}
{%- set end   = "left" if is_ar else "right" -%}

{#- ---------------- النصوص [عربي, English] ---------------- -#}
{%- set T = {
    "receipt":      ["سند قبض نقدية", "Receipt Voucher"],
    "payment":      ["سند صرف نقدية", "Payment Voucher"],
    "transfer":     ["سند تحويل داخلي", "Internal Transfer Voucher"],
    "recv_from":    ["استلمنا من السيد / السيدة", "Received from Mr. / Mrs."],
    "paid_to":      ["صرفنا إلى السيد / السيدة", "Paid to Mr. / Mrs."],
    "dept":         ["الإدارة المالية — الخزينة", "Finance Department — Treasury"],
    "tax_id":       ["رقم التسجيل الضريبي", "Tax Registration No."],
    "phone":        ["تليفون", "Phone"],
    "ac_year":      ["العام الدراسي", "Academic Year"],
    "voucher_no":   ["رقم السند", "Voucher No."],
    "date":         ["التاريخ", "Date"],
    "mop":          ["طريقة السداد", "Payment Method"],
    "status":       ["الحالة", "Status"],
    "party_no":     ["رقم", "No."],
    "from_acc":     ["من حساب", "From Account"],
    "to_acc":       ["إلى حساب", "To Account"],
    "sum_of":       ["مبلغاً وقدره", "The Sum of"],
    "cheque_no":    ["بشيك رقم", "Cheque No."],
    "ref_no":       ["رقم المرجع", "Reference No."],
    "cheque_date":  ["تاريخ الشيك", "Cheque Date"],
    "ref_date":     ["تاريخ المرجع", "Reference Date"],
    "being":        ["وذلك قيمة", "Being"],
    "amount":       ["المبلغ", "Amount"],
    "in_words":     ["المبلغ بالحروف", "Amount in Words"],
    "acc_details":  ["بيانات القيد", "Accounting Details"],
    "debit_acc":    ["الحساب المدين", "Debit Account"],
    "credit_acc":   ["الحساب الدائن", "Credit Account"],
    "cost_center":  ["مركز التكلفة", "Cost Center"],
    "project":      ["المشروع", "Project"],
    "ex_rate":      ["سعر الصرف", "Exchange Rate"],
    "recv_amount":  ["المبلغ المستلم", "Received Amount"],
    "clear_date":   ["تاريخ التسوية البنكية", "Clearance Date"],
    "refs":         ["المستندات المسددة", "Payment References"],
    "idx":          ["م", "#"],
    "doc_type":     ["نوع المستند", "Document Type"],
    "doc_no":       ["رقم المستند", "Document No."],
    "due_date":     ["تاريخ الاستحقاق", "Due Date"],
    "doc_amount":   ["قيمة المستند", "Document Amount"],
    "outstanding":  ["المتبقي قبل السداد", "Outstanding"],
    "allocated":    ["المبلغ المسدد", "Paid Amount"],
    "total":        ["الإجمالي", "Total"],
    "taxes":        ["الضرائب والرسوم", "Taxes & Charges"],
    "description":  ["البيان", "Description"],
    "rate":         ["النسبة", "Rate"],
    "deductions":   ["الخصومات والفروقات", "Deductions or Loss"],
    "account":      ["الحساب", "Account"],
    "unallocated":  ["مبلغ غير مخصص (تحت الحساب)", "Unallocated Amount (On Account)"],
    "total_taxes":  ["إجمالي الضرائب والرسوم", "Total Taxes & Charges"],
    "difference":   ["مبلغ الفرق", "Difference Amount"],
    "accountant":   ["المحاسب", "Accountant"],
    "cashier":      ["أمين الخزينة", "Cashier"],
    "fin_manager":  ["المدير المالي", "Finance Manager"],
    "sig_receiver": ["توقيع المستلم", "Receiver's Signature"],
    "sig_payer":    ["توقيع المسدِّد", "Payer's Signature"],
    "approved":     ["يعتمد", "Approved By"],
    "printed_by":   ["طُبع بواسطة", "Printed by"],
    "printed_on":   ["تاريخ الطباعة", "Printed on"],
    "at":           ["الساعة", "at"],
    "draft":        ["مسودة", "DRAFT"],
    "cancelled":    ["ملغي", "CANCELLED"],
    "p_refs":       ["سداد المستحقات طبقاً للمستندات الموضحة أدناه", "Settlement of dues as per the documents listed below"],
    "p_on_acc":     ["دفعة تحت الحساب", "Payment on account"],
    "p_advance":    ["دفعة مقدمة تحت الحساب", "Advance payment on account"],
} -%}

{#- ---------------- قواميس الترجمة للعربي (للبيانات القياسية) ---------------- -#}
{%- set AR_ONES  = ["", "واحد", "اثنان", "ثلاثة", "أربعة", "خمسة", "ستة", "سبعة", "ثمانية", "تسعة"] -%}
{%- set AR_TEENS = ["عشرة", "أحد عشر", "اثنا عشر", "ثلاثة عشر", "أربعة عشر", "خمسة عشر", "ستة عشر", "سبعة عشر", "ثمانية عشر", "تسعة عشر"] -%}
{%- set AR_TENS  = ["", "", "عشرون", "ثلاثون", "أربعون", "خمسون", "ستون", "سبعون", "ثمانون", "تسعون"] -%}
{%- set AR_HUND  = ["", "مائة", "مائتان", "ثلاثمائة", "أربعمائة", "خمسمائة", "ستمائة", "سبعمائة", "ثمانمائة", "تسعمائة"] -%}

{%- set CUR = {
    "EGP": ["جنيه مصري", "قرش", "ج.م", "قروش"],
    "USD": ["دولار أمريكي", "سنت", "دولار", "سنتات"],
    "EUR": ["يورو", "سنت", "يورو", "سنتات"],
    "SAR": ["ريال سعودي", "هللة", "ر.س", "هللات"],
    "AED": ["درهم إماراتي", "فلس", "د.إ", "فلوس"],
    "KWD": ["دينار كويتي", "فلس", "د.ك", "فلوس"],
} -%}

{%- set MOP = {
    "Cash": "نقداً", "Cheque": "شيك", "Bank Draft": "شيك مصرفي", "Wire Transfer": "تحويل بنكي",
    "Bank Transfer": "تحويل بنكي", "Credit Card": "بطاقة ائتمان", "Debit Card": "بطاقة خصم",
    "Instapay": "إنستاباي", "InstaPay": "إنستاباي", "Vodafone Cash": "فودافون كاش", "Fawry": "فوري",
} -%}

{%- set DOCTYPES = {
    "Sales Invoice": "فاتورة مبيعات", "Purchase Invoice": "فاتورة مشتريات", "Sales Order": "أمر بيع",
    "Purchase Order": "أمر شراء", "Journal Entry": "قيد يومية", "Fees": "رسوم دراسية",
    "Expense Claim": "مطالبة مصروفات", "Employee Advance": "سلفة موظف", "Dunning": "مطالبة سداد",
} -%}

{%- set PARTY_TYPES = {"Customer": "العميل", "Supplier": "المورد", "Employee": "الموظف",
                      "Student": "الطالب", "Shareholder": "المساهم"} -%}

{%- set STATUS = {"Submitted": "معتمد", "Draft": "مسودة", "Cancelled": "ملغي", "Reconciled": "تمت التسوية",
                 "Unreconciled": "لم تتم التسوية"} -%}

{#- ---------------- التفقيط العربي ---------------- -#}
{%- macro w99(n) -%}
    {%- if n == 0 -%}
    {%- elif n < 10 -%}{{ AR_ONES[n] }}
    {%- elif n < 20 -%}{{ AR_TEENS[n - 10] }}
    {%- elif n % 10 -%}{{ AR_ONES[n % 10] }} و{{ AR_TENS[n // 10] }}
    {%- else -%}{{ AR_TENS[n // 10] }}{%- endif -%}
{%- endmacro -%}

{%- macro w999(n) -%}
    {%- set h = AR_HUND[n // 100] -%}{%- set r = w99(n % 100) | trim -%}
    {{- h -}}{{- " و" if (h and r) else "" -}}{{- r -}}
{%- endmacro -%}

{%- macro scale(n, one, two, plural) -%}
    {%- if n == 0 -%}
    {%- elif n == 1 -%}{{ one }}
    {%- elif n == 2 -%}{{ two }}
    {%- elif 3 <= (n % 100) <= 10 -%}{{ w999(n) }} {{ plural }}
    {%- else -%}{{ w999(n) }} {{ one }}{%- endif -%}
{%- endmacro -%}

{%- macro tafqit(n) -%}
    {%- if n == 0 -%}صفر{%- else -%}
    {{- [ scale(n // 1000000000, "مليار", "ملياران", "مليارات") | trim,
          scale((n // 1000000) % 1000, "مليون", "مليونان", "ملايين") | trim,
          scale((n // 1000) % 1000, "ألف", "ألفان", "آلاف") | trim,
          w999(n % 1000) | trim ] | select | join(" و") -}}
    {%- endif -%}
{%- endmacro -%}

{%- macro money_ar(amount, currency) -%}
    {%- set c = CUR.get(currency) or [currency, "", currency, ""] -%}
    {%- set cents = ((amount or 0) * 100) | round | int -%}
    {%- set whole = cents // 100 -%}{%- set frac = cents % 100 -%}
    فقط {{ tafqit(whole) | trim }} {{ c[0] }}{% if frac %} و{{ tafqit(frac) | trim }} {{ c[3] if (3 <= frac <= 10 and c[3]) else c[1] }}{% endif %} لا غير
{%- endmacro -%}

{%- macro money_words(amount, currency) -%}
    {%- if is_ar -%}{{ money_ar(amount, currency) | trim }}
    {%- else -%}{{ frappe.utils.money_in_words(amount, currency) }}{%- endif -%}
{%- endmacro -%}

{%- macro tr(dct, v) -%}{{ (dct.get(v) or _(v)) if is_ar else v }}{%- endmacro -%}

{%- macro fullname(u) -%}
    {%- set fn = frappe.get_fullname or frappe.utils.get_fullname -%}
    {{- (fn(u) if fn else u) or "" -}}
{%- endmacro -%}

{%- macro num(v) -%}{{ frappe.utils.fmt_money(v or 0, precision=2) }}{%- endmacro -%}
{%- macro dt(v) -%}{{ frappe.utils.formatdate(v, "dd-MM-yyyy") if v else "" }}{%- endmacro -%}


{#- ---------------- نصوص قيد اليومية [عربي, English] ---------------- -#}
{%- set J = {
    "title":        ["قيد يومية", "Journal Voucher"],
    "entry_no":     ["رقم القيد", "Entry No."],
    "entry_type":   ["نوع القيد", "Entry Type"],
    "opening":      ["قيد افتتاحي", "Opening Entry"],
    "pay_to":       ["صرف إلى / استلام من", "Pay To / Received From"],
    "bill_no":      ["رقم الفاتورة", "Bill No."],
    "bill_date":    ["تاريخ الفاتورة", "Bill Date"],
    "finance_book": ["دفتر الحسابات", "Finance Book"],
    "lines":        ["تفاصيل القيد", "Entry Lines"],
    "party":        ["الطرف", "Party"],
    "line_note":    ["البيان", "Narration"],
    "acc_cur":      ["بعملة الحساب", "In Account Currency"],
    "debit":        ["مدين", "Debit"],
    "credit":       ["دائن", "Credit"],
    "totals":       ["الإجماليات", "Totals"],
    "remarks":      ["البيان العام للقيد", "Narration"],
    "reviewer":     ["المراجع", "Reviewed By"],
    "approver":     ["يعتمد", "Approved By"],
    "total_amount": ["قيمة القيد", "Entry Amount"],
    "ref":          ["مرجع", "Ref."],
} -%}

{%- set VTYPES = {
    "Journal Entry": "قيد يومية", "Inter Company Journal Entry": "قيد بين الشركات", "Bank Entry": "قيد بنكي",
    "Cash Entry": "قيد نقدي", "Credit Card Entry": "قيد بطاقة ائتمان", "Debit Note": "إشعار مدين",
    "Credit Note": "إشعار دائن", "Contra Entry": "قيد عكسي (تحويل)", "Excise Entry": "قيد ضريبة إنتاج",
    "Write Off Entry": "قيد إعدام / شطب", "Opening Entry": "قيد افتتاحي", "Depreciation Entry": "قيد إهلاك",
    "Exchange Rate Revaluation": "قيد إعادة تقييم عملة", "Exchange Gain Or Loss": "قيد فروق عملة",
    "Deferred Revenue": "إيراد مؤجل", "Deferred Expense": "مصروف مؤجل",
} -%}

{%- set PARTY_NAME_FIELD = {"Customer": "customer_name", "Supplier": "supplier_name", "Employee": "employee_name",
                           "Student": "student_name", "Shareholder": "title"} -%}

{#- ---------------- إعدادات عامة ---------------- -#}
{%- set c1 = "#14566b" -%}{%- set c2 = "#e7f3f6" -%}{%- set c3 = "#1f8aa6" -%}
{%- set comp = frappe.db.get_value("Company", doc.company, ["company_name", "company_logo", "tax_id", "phone_no", "default_currency"], as_dict=1) or {} -%}
{%- set cur_code = comp.default_currency or "EGP" -%}
{%- if is_ar -%}
    {%- set cur = CUR.get(cur_code) or [cur_code, "", cur_code] -%}
{%- else -%}
    {%- set cur = [frappe.db.get_value("Currency", cur_code, "currency_name") or cur_code, "", cur_code] -%}
{%- endif -%}
{%- set rows = doc.accounts or [] -%}
{%- set amount = doc.total_debit or 0 -%}
{%- set vtype = tr(VTYPES, doc.voucher_type) if doc.voucher_type else "" -%}
{%- set pd = frappe.utils.getdate(doc.posting_date) if doc.posting_date else frappe.utils.getdate() -%}
{%- set ay_start = pd.year if pd.month >= 9 else pd.year - 1 -%}

{%- set show_party = rows | selectattr("party") | list | length > 0 -%}
{%- set show_cc    = rows | selectattr("cost_center") | list | length > 0 -%}
{%- set show_prj   = rows | selectattr("project") | list | length > 0 -%}
{%- set show_ref   = rows | selectattr("reference_name") | list | length > 0 -%}
{%- set show_fx    = doc.multi_currency and (rows | rejectattr("account_currency", "equalto", cur_code) | list | length > 0) -%}

{%- macro acc_name(a) -%}{{ (frappe.db.get_value("Account", a, "account_name") or a) if a else "" }}{%- endmacro -%}
{%- macro cc_name(c) -%}{{ (frappe.db.get_value("Cost Center", c, "cost_center_name") or c) if c else "" }}{%- endmacro -%}
{%- macro prj_name(p) -%}{{ (frappe.db.get_value("Project", p, "project_name") or p) if p else "" }}{%- endmacro -%}
{%- macro party_name(pt, p) -%}
    {%- set f = PARTY_NAME_FIELD.get(pt) -%}
    {{- (frappe.db.get_value(pt, p, f) if f else "") or p -}}
{%- endmacro -%}

<style>
    .pe { direction: {{ dir }}; text-align: {{ start }}; font-family: "Tahoma", "Arial", sans-serif; color: #1f2933;
          font-size: 12px; position: relative; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    .pe table { width: 100%; border-collapse: collapse; }
    .pe td, .pe th { direction: {{ dir }}; text-align: {{ start }}; }
    .pe .ltr, .pe td.ltr { direction: ltr; unicode-bidi: embed; }

    /* ---------- الديباجة العلوية ---------- */
    .hd { border-bottom: 3px double {{ c1 }}; margin-bottom: 12px; }
    .hd td { vertical-align: middle; padding-bottom: 10px; }
    .hd td td { padding-bottom: 0; }
    .hd .school { font-size: 19px; font-weight: bold; color: {{ c1 }}; }
    .hd .dept { font-size: 12px; color: #52606d; padding-top: 3px; }
    .hd .sub { font-size: 10.5px; color: #7b8794; padding-top: 2px; }
    .ttl { background: {{ c1 }}; color: #fff; border-radius: 8px; padding: 9px 10px; text-align: center !important; }
    .ttl .t { font-size: 20px; font-weight: bold; }
    .ttl .y { font-size: 11px; padding-top: 2px; }
    .logo { max-height: 70px; max-width: 130px; }

    /* ---------- بطاقات البيانات ---------- */
    .chips { margin-bottom: 12px; }
    .chips td { padding: 0 3px; vertical-align: top; }
    .chip { background: {{ c2 }}; border: 1px solid {{ c3 }}; border-radius: 8px; padding: 6px 8px; text-align: center !important; }
    .chip .k { color: #52606d; font-size: 10px; }
    .chip .v { color: {{ c1 }}; font-weight: bold; font-size: 12.5px; }

    /* ---------- متن السند ---------- */
    .body { border: 1.5px solid {{ c1 }}; border-radius: 8px; margin-bottom: 14px; }
    .body td { padding: 9px 12px; vertical-align: middle; }
    .body td.k { width: {{ 150 if is_ar else 135 }}px; white-space: nowrap; font-weight: bold; color: {{ c1 }}; }
    .body td.v { border-bottom: 1.5px dotted #9aa5b1; font-size: 13px; }
    .body .big { font-size: 15px; font-weight: bold; }
    .amtbox { background: {{ c2 }}; border: 2px solid {{ c1 }}; border-radius: 8px; text-align: center !important; padding: 8px !important; }
    .amtbox .k { color: #52606d; font-size: 11px; }
    .amtbox .n { color: {{ c1 }}; font-size: 22px; font-weight: bold; }
    .amtbox .c { color: {{ c1 }}; font-size: 12px; font-weight: bold; }
    .body table.words { border: 1.5px dashed {{ c3 }}; }
    .body .words td { padding: 8px 10px; }
    .body .words td.wk { width: {{ 110 if is_ar else 120 }}px; white-space: nowrap; background: {{ c1 }}; color: #fff; font-weight: bold; text-align: center; }
    .body .words td.wv { background: {{ c2 }}; color: {{ c1 }}; font-weight: bold; font-size: {{ 13 if is_ar else 12 }}px; }

    /* ---------- الأقسام ---------- */
    .sec { margin-bottom: 14px; page-break-inside: avoid; }
    .sec-t { background: {{ c1 }}; color: #fff; font-weight: bold; font-size: 12.5px; padding: 6px 12px; border-radius: 6px 6px 0 0; }
    .sec-b { border: 1px solid #d9e2ec; border-top: 0; }

    .grid td { padding: 7px 10px; border-bottom: 1px solid #eef2f6; font-size: 11.5px; }
    .grid td.k { background: #f7f9fb; color: #52606d; font-weight: bold; width: 18%; white-space: nowrap; }
    .grid td.v { width: 32%; }

    .tbl th { background: {{ c2 }}; color: {{ c1 }}; font-size: 11px; padding: 7px 8px; border-bottom: 2px solid {{ c3 }}; }
    .tbl td { padding: 6px 8px; border-bottom: 1px solid #eef2f6; font-size: 11.5px; }
    .tbl tr:nth-child(even) td { background: #fafbfc; }
    .tbl .num { text-align: {{ end }} !important; direction: ltr; white-space: nowrap; }
    .tbl .idx { width: 26px; text-align: center !important; color: #9aa5b1; }
    .tbl tfoot td { background: {{ c2 }}; font-weight: bold; color: {{ c1 }}; border-top: 2px solid {{ c3 }}; }

    .tot { width: 48% !important; margin-{{ start }}: auto; margin-{{ end }}: 0; }
    .tot td { padding: 6px 10px; border-bottom: 1px solid #eef2f6; }
    .tot td.v { text-align: {{ end }} !important; direction: ltr; font-weight: bold; }

    /* ---------- التوقيعات ---------- */
    .sign { margin-top: 36px; page-break-inside: avoid; }
    .sign td { width: 25%; text-align: center !important; padding: 0 10px; vertical-align: bottom; }
    .sign .who { font-size: 10.5px; color: #52606d; height: 16px; }
    .sign .line { border-top: 1.5px solid {{ c1 }}; padding-top: 6px; font-weight: bold; color: {{ c1 }}; }

    .ft { margin-top: 18px; border-top: 1px solid #d9e2ec; }
    .ft td { padding-top: 6px; font-size: 9.5px; color: #9aa5b1; }

    .stamp { position: absolute; top: 330px; left: 0; right: 0; text-align: center !important; z-index: 0;
             font-size: 110px; font-weight: bold; opacity: .09;
             -webkit-transform: rotate(-25deg); transform: rotate(-25deg); }
    .cnt { position: relative; z-index: 1; }
    .letter-head { margin-bottom: 8px; }
    .letter-head img { max-width: 100%; }

    /* ---------- قيد اليومية ---------- */
    .tbl td { vertical-align: top; }
    .tbl .acc { font-weight: bold; }
    .tbl .meta { font-size: 10px; color: #7b8794; padding-top: 2px; }
    .tbl .meta span { display: inline-block; margin-{{ end }}: 8px; }
    .tbl .dr { color: #0b7a4b; }
    .tbl .cr { color: #a3282f; }
    .tbl tfoot td.num { font-size: 12.5px; }
    .ok   { color: #0b7a4b; }
    .bad  { color: #c0262d; }
    .remarks { padding: 10px 12px; line-height: 1.8; white-space: pre-line; }
</style>

{#- ================= الترويسة (Letter Head) من ERPNext ================= -#}
{%- set has_lh = letter_head and not no_letterhead -%}
{%- if has_lh -%}
<div class="letter-head">{{ letter_head }}</div>
{%- endif -%}

<div class="pe">
    {%- if doc.docstatus == 0 -%}<div class="stamp" style="color:#7b8794;">{{ T.draft[L] }}</div>
    {%- elif doc.docstatus == 2 -%}<div class="stamp" style="color:#c0262d; opacity:.14;">{{ T.cancelled[L] }}</div>{%- endif -%}

<div class="cnt">

    {#- ================= الديباجة العلوية ================= -#}
    {%- if has_lh -%}
    {#- يوجد ترويسة (Letter Head) مختارة: نكتفي بعنوان السند -#}
    <table class="hd"><tr>
        <td style="width:30%;"></td>
        <td style="width:40%;">
            <div class="ttl">
                <div class="t">{{ J.title[L] }}</div>
                <div class="y">{{ T.ac_year[L] }}</div><div class="y ltr" style="text-align:center;">{{ ay_start }} / {{ ay_start + 1 }}</div>
            </div>
        </td>
        <td style="width:30%;"></td>
    </tr></table>
    {%- else -%}
    <table class="hd"><tr>
        <td style="width:42%;">
            <div class="school">{{ comp.company_name or doc.company }}</div>
            <div class="dept">{{ T.dept[L] }}</div>
            {%- if comp.tax_id or comp.phone_no -%}
            <table style="width:auto;">
                {%- if comp.tax_id %}<tr><td class="sub">{{ T.tax_id[L] }} :</td><td class="sub ltr" style="padding-{{ start }}:6px; text-align:{{ start }};">{{ comp.tax_id }}</td></tr>{% endif -%}
                {%- if comp.phone_no %}<tr><td class="sub">{{ T.phone[L] }} :</td><td class="sub ltr" style="padding-{{ start }}:6px; text-align:{{ start }};">{{ comp.phone_no }}</td></tr>{% endif -%}
            </table>
            {%- endif -%}
        </td>
        <td style="width:30%;">
            <div class="ttl">
                <div class="t">{{ J.title[L] }}</div>
                <div class="y">{{ T.ac_year[L] }}</div><div class="y ltr" style="text-align:center;">{{ ay_start }} / {{ ay_start + 1 }}</div>
            </div>
        </td>
        <td style="width:28%; text-align:{{ end }};">
            {%- if comp.company_logo %}<img class="logo" src="{{ comp.company_logo }}">{% endif -%}
        </td>
    </tr></table>
    {%- endif -%}

    {#- ================= بطاقات البيانات ================= -#}
    {%- set chips = [
        (J.entry_no[L], doc.name),
        (T.date[L], dt(doc.posting_date)),
        (J.entry_type[L], vtype),
        (J.opening[L] if doc.is_opening == "Yes" else "", "✓" if doc.is_opening == "Yes" else ""),
        (T.status[L], tr(STATUS, doc.status) if (doc.status and doc.docstatus != 0) else ""),
    ] | selectattr("1") | list -%}
    <table class="chips"><tr>
        {%- for ch in chips -%}
        <td style="width:{{ (100 / chips|length)|int }}%;">
            <div class="chip"><div class="k">{{ ch[0] }}</div><div class="v {{ 'ltr' if loop.first else '' }}">{{ ch[1] }}</div></div>
        </td>
        {%- endfor -%}
    </tr></table>

    {#- ================= بيانات القيد (المملوء فقط) ================= -#}
    {%- set is_cheque = doc.voucher_type == "Bank Entry" or doc.mode_of_payment in ["Cheque", "Bank Draft"] -%}
    {%- set details = [
        (J.pay_to[L], doc.pay_to_recd_from),
        (T.mop[L], tr(MOP, doc.mode_of_payment) if doc.mode_of_payment else ""),
        (T.cheque_no[L] if is_cheque else T.ref_no[L], doc.cheque_no),
        (T.cheque_date[L] if is_cheque else T.ref_date[L], dt(doc.cheque_date)),
        (J.bill_no[L], doc.bill_no),
        (J.bill_date[L], dt(doc.bill_date)),
        (T.due_date[L], dt(doc.due_date)),
        (J.finance_book[L], doc.finance_book),
        (T.clear_date[L], dt(doc.clearance_date)),
    ] | selectattr("1") | list -%}
    {%- if details -%}
    <div class="sec">
        <div class="sec-t">{{ T.acc_details[L] }}</div>
        <div class="sec-b"><table class="grid">
            {%- for pair in details | batch(2) -%}
            <tr>
                {%- for it in pair -%}<td class="k">{{ it[0] }}</td><td class="v">{{ it[1] }}</td>{%- endfor -%}
                {%- if pair | length == 1 -%}<td class="k" style="background:#fff;"></td><td class="v"></td>{%- endif -%}
            </tr>
            {%- endfor -%}
        </table></div>
    </div>
    {%- endif -%}

    {#- ================= سطور القيد ================= -#}
    {%- if rows -%}
    <div class="sec">
        <div class="sec-t">{{ J.lines[L] }}</div>
        <div class="sec-b"><table class="tbl">
            <thead><tr>
                <th class="idx">{{ T.idx[L] }}</th>
                <th>{{ T.account[L] }}</th>
                {%- if show_party %}<th>{{ J.party[L] }}</th>{% endif -%}
                {%- if show_cc %}<th>{{ T.cost_center[L] }}</th>{% endif -%}
                {%- if show_prj %}<th>{{ T.project[L] }}</th>{% endif -%}
                {%- if show_fx %}<th class="num">{{ J.acc_cur[L] }}</th>{% endif -%}
                <th class="num">{{ J.debit[L] }}</th>
                <th class="num">{{ J.credit[L] }}</th>
            </tr></thead>
            <tbody>
            {%- for r in rows -%}
                <tr>
                    <td class="idx">{{ loop.index }}</td>
                    <td>
                        <div class="acc">{{ acc_name(r.account) }}</div>
                        {%- if r.reference_name or r.user_remark -%}
                        <div class="meta">
                            {%- if r.reference_name %}<span>{{ J.ref[L] }}: {{ tr(DOCTYPES, r.reference_type) }} <span class="ltr">{{ r.reference_name }}</span></span>{% endif -%}
                            {%- if r.user_remark %}<span>{{ r.user_remark }}</span>{% endif -%}
                        </div>
                        {%- endif -%}
                    </td>
                    {%- if show_party -%}
                    <td>
                        {%- if r.party -%}
                            <div>{{ party_name(r.party_type, r.party) }}</div>
                            <div class="meta ltr" style="text-align:{{ start }};">{{ r.party }}</div>
                        {%- endif -%}
                    </td>
                    {%- endif -%}
                    {%- if show_cc %}<td>{{ cc_name(r.cost_center) }}</td>{% endif -%}
                    {%- if show_prj %}<td>{{ prj_name(r.project) }}</td>{% endif -%}
                    {%- if show_fx -%}
                    <td class="num">
                        {%- if r.account_currency and r.account_currency != cur_code -%}
                            {{ num(r.debit_in_account_currency or r.credit_in_account_currency) }} {{ r.account_currency }}
                            <div class="meta">× {{ r.exchange_rate }}</div>
                        {%- endif -%}
                    </td>
                    {%- endif -%}
                    <td class="num dr">{{ ("<b>" ~ num(r.debit) ~ "</b>") | safe if r.debit else "" }}</td>
                    <td class="num cr">{{ ("<b>" ~ num(r.credit) ~ "</b>") | safe if r.credit else "" }}</td>
                </tr>
            {%- endfor -%}
            </tbody>
            {%- set span = 2 + (1 if show_party else 0) + (1 if show_cc else 0) + (1 if show_prj else 0) + (1 if show_fx else 0) -%}
            <tfoot><tr>
                <td colspan="{{ span }}">{{ J.totals[L] }} ({{ cur[2] }})</td>
                <td class="num">{{ num(doc.total_debit) }}</td>
                <td class="num">{{ num(doc.total_credit) }}</td>
            </tr>
            {%- if doc.difference -%}
            <tr><td colspan="{{ span }}" class="bad">{{ T.difference[L] }}</td><td colspan="2" class="num bad">{{ num(doc.difference) }}</td></tr>
            {%- endif -%}
            </tfoot>
        </table></div>
    </div>
    {%- endif -%}

    {#- ================= قيمة القيد بالحروف ================= -#}
    {%- if amount -%}
    <table class="body sec"><tr><td style="padding:10px;">
        <table class="words"><tr>
            <td class="wk">{{ J.total_amount[L] }}</td>
            <td class="wv" style="width:150px; white-space:nowrap;"><span class="ltr">{{ num(amount) }}</span> {{ cur[2] }}</td>
            <td class="wv">{{ money_words(amount, cur_code) | trim }}</td>
        </tr></table>
    </td></tr></table>
    {%- endif -%}

    {#- ================= البيان العام ================= -#}
    {%- if doc.user_remark and doc.user_remark | trim -%}
    <div class="sec">
        <div class="sec-t">{{ J.remarks[L] }}</div>
        <div class="sec-b remarks">{{ doc.user_remark }}</div>
    </div>
    {%- endif -%}

    {#- ================= التوقيعات ================= -#}
    <table class="sign"><tr>
        <td><div class="who">{{ fullname(doc.owner) }}</div><div class="line">{{ T.accountant[L] }}</div></td>
        <td><div class="who"></div><div class="line">{{ J.reviewer[L] }}</div></td>
        <td><div class="who"></div><div class="line">{{ T.fin_manager[L] }}</div></td>
        <td><div class="who"></div><div class="line">{{ J.approver[L] }}</div></td>
    </tr></table>

    <table class="ft"><tr>
        <td style="width:50%;">{{ T.printed_by[L] }}: {{ fullname(frappe.session.user) }}</td>
        <td style="width:50%; text-align:{{ end }};">{{ T.printed_on[L] }}: {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "dd-MM-yyyy") }} &nbsp;{{ T.at[L] }} {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "HH:mm") }}</td>
    </tr></table>

</div>
</div>

{%- if footer and not no_letterhead -%}
<div id="footer-html" class="visible-pdf">
    <div class="letter-head-footer">{{ footer }}</div>
</div>
{%- endif -%}

{#- ============================================================
    سند قبض / صرف – Payment Entry (ERPNext)
    - عربي / إنجليزي تلقائياً حسب لغة النظام أو لغة الطباعة المختارة
    - العربي: اتجاه من اليمين + تفقيط عربي داخلي
    - الإنجليزي: اتجاه من اليسار + تفقيط ERPNext الإنجليزي
    - لون وعنوان حسب نوع الدفع
    - لا يظهر إلا الحقول / الأعمدة / الأقسام التي بها قيم
   ============================================================ -#}

{#- ---------------- تحديد اللغة ---------------- -#}
{#- أولاً من ترجمة النظام الحالية (تتبع لغة الطباعة المختارة)، وإلا من frappe.lang -#}
{%- set _probe = _("Debit") | string -%}
{%- if _probe != "Debit" and _probe | length > 0 -%}
    {%- set is_ar = "\u0600" <= _probe[0] <= "\u06FF" -%}
{%- else -%}
    {%- set is_ar = ((frappe.lang or "en") | string | lower).startswith("ar") -%}
{%- endif -%}
{%- set L = 0 if is_ar else 1 -%}
{%- set dir   = "rtl" if is_ar else "ltr" -%}
{%- set start = "right" if is_ar else "left" -%}
{%- set end   = "left" if is_ar else "right" -%}

{#- ---------------- النصوص [عربي, English] ---------------- -#}
