		<td><div class="line">{%= t("accountant") %}</div></td>
		<td><div class="line">{%= t("reviewer") %}</div></td>
		<td><div class="line">{%= t("fin_manager") %}</div></td>
		<td><div class="line">{%= t("general_manager") %}</div></td>
	</tr></table>
	{% } %}

	<table class="ft"><tr>
		<td style="width:50%;">{%= t("printed_by") %}: {%= esc((frappe.session && (frappe.session.user_fullname || frappe.session.user)) || "") %}</td>
		<td style="width:50%; text-align:{%= E %};">{%= t("printed_on") %}: <span class="ltr">{%= frappe.datetime.str_to_user(frappe.datetime.now_datetime()) %}</span></td>
	</tr></table>
</div>

