	if (!isempty(tot.debit)) CARDS.push([t("mv_debit"), fnum(tot.debit), ""]);
	if (!isempty(tot.credit)) CARDS.push([t("mv_credit"), fnum(tot.credit), ""]);
	if (!isempty(tot.closing_debit)) CARDS.push([t("cl_debit"), fnum(tot.closing_debit), ""]);
	if (!isempty(tot.closing_credit)) CARDS.push([t("cl_credit"), fnum(tot.closing_credit), ""]);
	var diff = flt(tot.closing_debit) - flt(tot.closing_credit);
	if (C.kind === "tb" && (tot.closing_debit || tot.closing_credit)) {
		CARDS.push(Math.abs(diff) < 0.01 ? [t("balanced"), "&#10004;", "ok"] : [t("unbalanced"), fnum(diff), "bad"]);
	}
	CARDS.push([C.kind === "tbp" ? t("parties") : t("accounts"), String(entries.length), "muted"]);
}
if (C.kind === "gl") {
	var op = null, cl = null, sdr = 0, scr = 0, n = 0, lastbal = null;
	DATA.forEach(function (r) {
		if (!r) return;
		var s = special_key(r);
		if (s === "opening") op = r;
		else if (s && s.indexOf("closing") === 0) cl = r;
		else if (r.posting_date) { sdr += flt(r.debit); scr += flt(r.credit); n++; lastbal = r.balance; }
	});
	if (op && !isempty(op.balance)) CARDS.push([t("gl_opening"), fnum(Math.abs(flt(op.balance)), 2, true) + " <small>" + (flt(op.balance) < 0 ? t("cr") : t("dr")) + "</small>", ""]);
	CARDS.push([t("gl_debit"), fnum(sdr), ""]);
	CARDS.push([t("gl_credit"), fnum(scr), ""]);
	var cb = cl ? cl.balance : lastbal;
	if (cb != null) CARDS.push([t("gl_closing"), fnum(Math.abs(flt(cb)), 2, true) + " <small>" + (flt(cb) < 0 ? t("cr") : t("dr")) + "</small>", "hl"]);
	CARDS.push([t("entries"), String(n), "muted"]);
}
var UNP_N = 0, UNP_AMT = 0;
entries.forEach(function (r) { if (is_unposted(r)) { UNP_N++; UNP_AMT += flt(r.debit); } });
if (UNP_N) CARDS.push([t("unposted_count"), String(UNP_N) + (UNP_AMT ? " <small>(" + fnum(UNP_AMT) + ")</small>" : ""), "warn"]);
if (C.kind === "fs") {
	var lastnum = NUM.length ? NUM[NUM.length - 1].fieldname : null;
	if (lastnum) {
		var keyrows = DATA.filter(function (r) { return r && !row_blank(r) && (is_total(r) || ((r.bold || r.bold_text) && !cint(r.indent))) && !isempty(r[lastnum]); });
		keyrows.slice(-4).forEach(function (r, i, arr) {
			CARDS.push([esc(unq(r.account_name || r.section_name || r.section || r.account)), fnum(r[lastnum]), i === arr.length - 1 ? "hl" : ""]);
		});
	}
}
if (C.kind === "ls") {
	var lt = null;
	for (var li = DATA.length - 1; li >= 0; li--) { if (DATA[li] && is_total(DATA[li])) { lt = DATA[li]; break; } }
	var sums = {};
	["opening_balance", "invoiced_amount", "paid_amount", "return_amount", "closing_balance"].forEach(function (f) {
		sums[f] = lt && lt[f] != null && lt[f] !== "" ? flt(lt[f]) : entries.reduce(function (a, r) { return a + flt(r[f]); }, 0);
	});
	if (!isempty(sums.opening_balance)) CARDS.push([t("ls_opening"), fnum(sums.opening_balance), ""]);
	if (!isempty(sums.invoiced_amount)) CARDS.push([t("ls_invoiced"), fnum(sums.invoiced_amount), ""]);
	if (!isempty(sums.paid_amount)) CARDS.push([t("ls_paid"), fnum(sums.paid_amount), ""]);
	if (!isempty(sums.return_amount)) CARDS.push([t("ls_return"), fnum(sums.return_amount), ""]);
	CARDS.push([t("ls_closing"), fnum(sums.closing_balance), "hl"]);
	CARDS.push([t("parties"), String(entries.length), "muted"]);
}

function first_cell(r) {
	var c0 = COLS[0];
	if (C.kind === "fs" || C.kind === "tb") {
		var name = unq(r.account_name || r.section_name || r[c0.fieldname]);
		var pad = cint(r.indent) * 14;
		var pre = r.prefix ? esc(r.prefix) + " " : "";
		return "<span style=\"padding-" + S + ":" + pad + "px\">" + pre + esc(name) + "</span>";
	}
	if (C.kind === "tbp" || C.kind === "ls") {
		var nm = r.party_name || "";
		var id = unq(r.party);
		if (nm && nm !== id) return "<div class=\"nm\">" + esc(nm) + "</div><div class=\"sub id\">" + esc(id) + "</div>";
		return "<div class=\"nm\">" + esc(id) + "</div>";
	}
	return cell(c0, r);
}

function cell(c, r) {
	var f = c.fieldname, v = r[f];
	if (isnum(c)) {
		if (C.kind === "gl" && f === "balance" && typeof v === "number" && r.posting_date && Math.abs(v) < 0.005) return fnum(0);
		if (isempty(v)) return "";
		if (c.fieldtype === "Percent") return fnum(v, 2) + " %";
		if (C.kind === "gl" && f === "balance") {
			return fnum(Math.abs(flt(v)), 2, true) + " <span class=\"drcr " + (flt(v) < 0 ? "c" : "d") + "\">" + (flt(v) < 0 ? t("cr") : t("dr")) + "</span>";
		}
		return fnum(v, decs(c));
	}
	if (isempty(v)) return "";
	if (c.fieldtype === "Date" || f === "posting_date") return "<span class=\"ltr nowrap\">" + pdate(v) + "</span>";
	if (f === "voucher_no") {
		var vt = r.voucher_type ? "<div class=\"sub\">" + esc(tv(r.voucher_type)) + (r.voucher_subtype && r.voucher_subtype !== r.voucher_type ? " / " + esc(__(r.voucher_subtype)) : "") + "</div>" : "";
		return "<div class=\"id strong\">" + esc(v) + "</div>" + vt;
	}
	if (f === "party") {
		var pt = r.party_type && SKIP.indexOf("party_type") !== -1 ? "<div class=\"sub\">" + esc(tv(r.party_type)) + "</div>" : "";
		return "<div" + (/^[A-Za-z0-9._\/-]+$/.test(String(v)) ? " class=\"id\"" : "") + ">" + esc(v) + "</div>" + pt;
	}
	if (f === "against_voucher") {
		var avt = r.against_voucher_type && SKIP.indexOf("against_voucher_type") !== -1 ? "<div class=\"sub\">" + esc(tv(r.against_voucher_type)) + "</div>" : "";
		return "<div class=\"id\">" + esc(v) + "</div>" + avt;
	}
	if (f === "voucher_type" || f === "party_type" || f === "against_voucher_type") return esc(tv(v));
	if (f === "dr_or_cr") return AR ? (String(v).toLowerCase().indexOf("cr") === 0 ? "دائن" : "مدين") : esc(v);
	if (Array.isArray(v)) return esc(v.join(", "));
	if (LINK_STRIP.indexOf(f) !== -1) return esc(noabbr(unq(v)));
	return esc(unq(v));
}

var BADGE_COL = COLS.some(function (c) { return c.fieldname === "voucher_no"; }) ? "voucher_no" : (COLS.length ? COLS[0].fieldname : "");
var H = [];
if (UNP_N) H.push("<div class=\"unp-legend\"><span class=\"sw\"></span>" + t("unposted_legend") + " (" + UNP_N + ")</div>");
H.push("<table class=\"rt\"><thead>");
if (HAS_GROUPS) {
	H.push("<tr>");
	var i2 = 0;
	while (i2 < COLS.length) {
		var g = grp(COLS[i2].fieldname);
		if (!g) {
			H.push("<th rowspan=\"2\" class=\"" + (isnum(COLS[i2]) ? "num" : "") + (i2 === 0 ? " c0" : "") + "\">" + lbl(COLS[i2]) + "</th>");
			i2++;
		} else {
			var span = 0;
			while (i2 + span < COLS.length && grp(COLS[i2 + span].fieldname) === g) span++;
			H.push("<th colspan=\"" + span + "\" class=\"grp " + g + "\">" + t(g) + "</th>");
			i2 += span;
		}
	}
	H.push("</tr><tr>");
	COLS.forEach(function (c) {
		var g = grp(c.fieldname);
		if (g) H.push("<th class=\"num sub2 " + g + "\">" + (c.fieldname.indexOf("credit") !== -1 ? t("credit") : t("debit")) + "</th>");
	});
	H.push("</tr>");
} else {
	H.push("<tr>");
	COLS.forEach(function (c, idx) { H.push("<th class=\"" + (isnum(c) ? "num" : "") + (idx === 0 ? " c0" : "") + "\">" + lbl(c) + "</th>"); });
	H.push("</tr>");
}
H.push("</thead><tbody>");

var LAST_SPECIAL = null;
for (var ls_i = DATA.length - 1; ls_i >= 0; ls_i--) { if (DATA[ls_i] && !row_blank(DATA[ls_i])) { if (is_total(DATA[ls_i])) LAST_SPECIAL = DATA[ls_i]; break; } }
var printed = 0, pending_gap = false;
DATA.forEach(function (r) {
	if (!r) return;
	if (row_blank(r)) { if (printed) pending_gap = true; return; }
	if (pending_gap) { H.push("<tr class=\"gap\"><td colspan=\"" + COLS.length + "\"></td></tr>"); pending_gap = false; }
	var tot = is_total(r);
	var cls = [];
	if (tot) {
		var sk = special_key(r) || "total";
		cls.push(sk === "opening" ? "opening" : ((sk.indexOf("closing") === 0 || r === LAST_SPECIAL) ? "closing" : "total"));
	} else {
		if (r.bold || r.bold_text || cint(r.is_group_account) || cint(r.is_group)) cls.push("grp-row");
		if (r.italic || r.italic_text || r.is_detail) cls.push("it");
		if (is_head(r)) cls.push("lvl0");
		if (is_head(r) && cls.indexOf("grp-row") === -1) cls.push("grp-row");
		if (is_unposted(r)) cls.push("unposted");
	}
	H.push("<tr class=\"" + cls.join(" ") + "\"" + (r.color && !tot ? " style=\"color:" + esc(r.color) + "\"" : "") + ">");
	if (tot) {
		var lead = 0;
		while (lead < COLS.length && !isnum(COLS[lead])) lead++;
		if (lead === 0) lead = 1;
		H.push("<td colspan=\"" + lead + "\" class=\"c0\">" + special_label(r) + "</td>");
		for (var j = lead; j < COLS.length; j++) {
			H.push("<td class=\"" + (isnum(COLS[j]) ? "num" : "") + "\">" + cell(COLS[j], r) + "</td>");
		}
	} else {
		COLS.forEach(function (c, idx) {
			var g = grp(c.fieldname);
			var k = (isnum(c) ? "num" : "") + (idx === 0 ? " c0" : "") + (g ? " " + g : "") + (c.fieldname === "remarks" ? " rm" : "") + (C.kind === "gl" && c.fieldname === "debit" ? " dr-col" : "") + (C.kind === "gl" && c.fieldname === "credit" ? " cr-col" : "");
			var content = idx === 0 ? first_cell(r) : cell(c, r);
			if (c.fieldname === BADGE_COL && is_unposted(r)) content += "<div><span class=\"unp-badge\">" + t("unposted") + "</span></div>";
			H.push("<td class=\"" + k + "\">" + content + "</td>");
		});
	}
	H.push("</tr>");
	printed++;
});
if (!printed) H.push("<tr><td colspan=\"" + Math.max(COLS.length, 1) + "\" class=\"empty\">" + t("no_data") + "</td></tr>");
H.push("</tbody></table>");
