		if (g) H.push("<th class=\"num sub2 " + g + "\">" + (c.fieldname.indexOf("credit") !== -1 ? t("credit") : t("debit")) + "</th>");
	});
	H.push("</tr>");
} else {
	H.push("<tr>");
	COLS.forEach(function (c, idx) { H.push("<th class=\"" + (isnum(c) ? "num" : "") + (idx === 0 ? " c0" : "") + "\">" + lbl(c) + "</th>"); });
	H.push("</tr>");
}
H.push("</thead><tbody>");

var LAST_SPECIAL = null;
for (var ls_i = DATA.length - 1; ls_i >= 0; ls_i--) { if (DATA[ls_i] && !row_blank(DATA[ls_i])) { if (is_total(DATA[ls_i])) LAST_SPECIAL = DATA[ls_i]; break; } }
var printed = 0, pending_gap = false;
DATA.forEach(function (r) {
	if (!r) return;
	if (row_blank(r)) { if (printed) pending_gap = true; return; }
	if (pending_gap) { H.push("<tr class=\"gap\"><td colspan=\"" + COLS.length + "\"></td></tr>"); pending_gap = false; }
	var tot = is_total(r);
	var cls = [];
	if (tot) {
		var sk = special_key(r) || "total";
		cls.push(sk === "opening" ? "opening" : ((sk.indexOf("closing") === 0 || r === LAST_SPECIAL) ? "closing" : "total"));
	} else {
		if (r.bold || r.bold_text || cint(r.is_group_account) || cint(r.is_group)) cls.push("grp-row");
		if (r.italic || r.italic_text || r.is_detail) cls.push("it");
		if (is_head(r)) cls.push("lvl0");
		if (is_head(r) && cls.indexOf("grp-row") === -1) cls.push("grp-row");
		if (is_unposted(r)) cls.push("unposted");
	}
	H.push("<tr class=\"" + cls.join(" ") + "\"" + (r.color && !tot ? " style=\"color:" + esc(r.color) + "\"" : "") + ">");
	if (tot) {
		var lead = 0;
		while (lead < COLS.length && !isnum(COLS[lead])) lead++;
		if (lead === 0) lead = 1;
		H.push("<td colspan=\"" + lead + "\" class=\"c0\">" + special_label(r) + "</td>");
		for (var j = lead; j < COLS.length; j++) {
			H.push("<td class=\"" + (isnum(COLS[j]) ? "num" : "") + "\">" + cell(COLS[j], r) + "</td>");
		}
	} else {
		COLS.forEach(function (c, idx) {
			var g = grp(c.fieldname);
			var k = (isnum(c) ? "num" : "") + (idx === 0 ? " c0" : "") + (g ? " " + g : "") + (c.fieldname === "remarks" ? " rm" : "") + (C.kind === "gl" && c.fieldname === "debit" ? " dr-col" : "") + (C.kind === "gl" && c.fieldname === "credit" ? " cr-col" : "");
			var content = idx === 0 ? first_cell(r) : cell(c, r);
			if (c.fieldname === BADGE_COL && is_unposted(r)) content += "<div><span class=\"unp-badge\">" + t("unposted") + "</span></div>";
			H.push("<td class=\"" + k + "\">" + content + "</td>");
		});
	}
	H.push("</tr>");
	printed++;
});
if (!printed) H.push("<tr><td colspan=\"" + Math.max(COLS.length, 1) + "\" class=\"empty\">" + t("no_data") + "</td></tr>");
H.push("</tbody></table>");
