<div class="rp">
	<table class="hdr"><tr>
		<td style="width:62%;">
			<div class="ttl">{%= TITLE %}</div>
			<div class="alt">{%= TITLE_ALT %}</div>
			{% if (C.kind === "fs" && F.report_template) { %}<div class="tpl">{%= esc(__(F.report_template)) %}</div>{% } %}
		</td>
		<td style="width:38%;">
			{% if (F.company) { %}<div class="co">{%= esc(F.company) %}</div>{% } %}
			<div class="pr">{%= t("printed_on") %}: <span class="ltr">{%= frappe.datetime.str_to_user(frappe.datetime.now_datetime()) %}</span></div>
		</td>
	</tr></table>
	<div class="stripe1"></div><div class="stripe2"></div>

	{% if (CHIPS.length) { %}
	<table class="chips">
		{% for (var ci = 0; ci < CHIPS.length; ci += 4) { %}
		<tr>
			{% for (var cj = ci; cj < ci + 4; cj++) { %}
			<td style="width:25%;">
				{% if (cj < CHIPS.length) { %}<div class="chip"><div class="k">{%= CHIPS[cj][0] %}</div><div class="v">{%= CHIPS[cj][1] %}</div></div>{% } %}
			</td>
			{% } %}
		</tr>
		{% } %}
	</table>
	{% } %}

	{% if (CARDS.length) { %}
	<table class="cards"><tr>
		{% for (var k = 0; k < CARDS.length; k++) { %}
		<td style="width:{%= Math.floor(100 / CARDS.length) %}%;">
			<div class="card {%= CARDS[k][2] %}"><div class="k">{%= CARDS[k][0] %}</div><div class="v">{%= CARDS[k][1] %}</div></div>
		</td>
		{% } %}
	</tr></table>
	{% } %}

	{% if (subtitle && String(subtitle).trim()) { %}
	<div class="crit"><b>{%= t("filters") %}:</b> {%= subtitle %}</div>
	{% } %}

	{%= H.join("") %}

	{% if (C.signatures === 3) { %}
	<table class="sign"><tr>
		<td><div class="line">{%= AR ? "أعدّه" : "Prepared By" %}</div></td>
		<td><div class="line">{%= t("reviewer") %}</div></td>
		<td><div class="line">{%= AR ? "اعتمده" : "Approved By" %}</div></td>
