	.rp .rt td.c0 { min-width: 140px; }
	.rp .rt td, .rp .chip .v, .rp .card .k { unicode-bidi: plaintext; }
	.rp .rt td.num { unicode-bidi: embed; }
	.rp .rt td.rm { font-size: 10px; color: #44546a; max-width: 260px; }
	.rp .rt .sub { font-size: 9px; color: #6b7a8c; }
	.rp .rt .id { white-space: nowrap; direction: ltr; unicode-bidi: embed; }
	.rp .rt .strong { color: {%= C.c1 %}; }
	.rp .rt .nm { font-weight: bold; color: {%= C.c1 %}; }
	.rp .rt td.dr-col { color: {%= C.c1 %}; }
	.rp .rt td.cr-col { color: #b23a3a; }
	.rp .rt tbody tr.grp-row td { font-weight: bold; color: {%= C.c1 %}; }
	.rp .rt tbody tr.lvl0 td { background: {%= C.c2 %} !important; border-top: 1px solid #dce3ec; }
	.rp .rt tbody tr.it td { font-style: italic; color: #6b7a8c; }
	.rp .rt tbody tr.total td { background: {%= C.c2 %} !important; color: {%= C.c1 %}; font-weight: bold; border-top: 2px solid {%= C.c1 %}; }
	.rp .rt tbody tr.opening td { background: {%= C.op_bg || "#fff6e6" %} !important; color: {%= C.op_fg || "#8a5a00" %}; font-weight: bold; border-bottom: 2px solid {%= C.ac || "#e2a23b" %}; }
	.rp .rt tbody tr.closing td { background: {%= C.c1 %} !important; color: #fff; font-weight: bold; font-size: 11.5px; }
	.rp .rt tbody tr.closing td .neg { color: #ffd9d9; }
	.rp .rt tbody tr.gap td { height: 5px; padding: 0; background: #fff !important; border-bottom: 1px solid #dce3ec; }
	.rp .rt tbody tr.unposted td { background: #fff8ef !important; color: #b4561a; font-style: italic; }
	.rp .rt tbody tr.unposted td .sub, .rp .rt tbody tr.unposted td .strong { color: #b4561a; }
	.rp .rt tbody tr.unposted td.c0 { border-{%= S %}: 4px solid #e39a5b; }
	.rp .unp-badge { display: inline-block; font-style: normal; font-size: 8.5px; font-weight: bold; color: #9a4a14; background: #fde7d2; border-radius: 3px; padding: 0 5px; margin-top: 2px; }
	.rp .unp-legend { font-size: 10px; color: #9a4a14; background: #fff8ef; border: 1px solid #f2d3ad; border-radius: 6px; padding: 4px 10px; margin-bottom: 6px; display: inline-block; }
	.rp .unp-legend .sw { display: inline-block; width: 10px; height: 10px; background: #e39a5b; border-radius: 2px; margin-{%= E %}: 6px; vertical-align: middle; }
	.rp .rt td.empty { text-align: center; padding: 18px; color: #6b7a8c; }
	.rp .neg { color: #b23a3a; }
	.rp .drcr { font-size: 8.5px; font-weight: bold; padding: 1px 4px; border-radius: 3px; margin-{%= S %}: 3px; }
	.rp .drcr.d { color: {%= C.c1 %}; background: #e4ecf6; }
	.rp .drcr.c { color: #b23a3a; background: #f8e3e3; }
	.rp tr.closing .drcr { color: {%= C.c1 %}; background: {%= C.ac || "#e8d9b0" %}; }
	.rp tr.opening .drcr.d { background: #f6e7c8; color: #8a5a00; }

	.rp .sign { margin-top: 34px; page-break-inside: avoid; }
	.rp .sign td { width: 25%; text-align: center; padding: 0 10px; vertical-align: bottom; }
	.rp .sign .line { border-top: 1px solid #9aa5b1; padding-top: 6px; color: #6b7a8c; font-size: 11px; }
	.rp .ft { margin-top: 14px; border-top: 1px solid #e3e8ef; }
	.rp .ft td { padding-top: 5px; font-size: 9px; color: #9aa5b1; }
</style>

<div class="rp">
	<table class="hdr"><tr>
		<td style="width:62%;">
			<div class="ttl">{%= TITLE %}</div>
			<div class="alt">{%= TITLE_ALT %}</div>
			{% if (C.kind === "fs" && F.report_template) { %}<div class="tpl">{%= esc(__(F.report_template)) %}</div>{% } %}
		</td>
		<td style="width:38%;">
			{% if (F.company) { %}<div class="co">{%= esc(F.company) %}</div>{% } %}
			<div class="pr">{%= t("printed_on") %}: <span class="ltr">{%= frappe.datetime.str_to_user(frappe.datetime.now_datetime()) %}</span></div>
		</td>
	</tr></table>
	<div class="stripe1"></div><div class="stripe2"></div>

	{% if (CHIPS.length) { %}
	<table class="chips">
		{% for (var ci = 0; ci < CHIPS.length; ci += 4) { %}
		<tr>
			{% for (var cj = ci; cj < ci + 4; cj++) { %}
			<td style="width:25%;">
				{% if (cj < CHIPS.length) { %}<div class="chip"><div class="k">{%= CHIPS[cj][0] %}</div><div class="v">{%= CHIPS[cj][1] %}</div></div>{% } %}
			</td>
			{% } %}
		</tr>
		{% } %}
	</table>
	{% } %}

	{% if (CARDS.length) { %}
	<table class="cards"><tr>
		{% for (var k = 0; k < CARDS.length; k++) { %}
		<td style="width:{%= Math.floor(100 / CARDS.length) %}%;">
			<div class="card {%= CARDS[k][2] %}"><div class="k">{%= CARDS[k][0] %}</div><div class="v">{%= CARDS[k][1] %}</div></div>
		</td>
		{% } %}
	</tr></table>
	{% } %}

	{% if (subtitle && String(subtitle).trim()) { %}
	<div class="crit"><b>{%= t("filters") %}:</b> {%= subtitle %}</div>
	{% } %}

	{%= H.join("") %}

	{% if (C.signatures === 3) { %}
	<table class="sign"><tr>
		<td><div class="line">{%= AR ? "أعدّه" : "Prepared By" %}</div></td>
		<td><div class="line">{%= t("reviewer") %}</div></td>
		<td><div class="line">{%= AR ? "اعتمده" : "Approved By" %}</div></td>
	</tr></table>
	{% } else if (C.signatures) { %}
	<table class="sign"><tr>
		<td><div class="line">{%= t("accountant") %}</div></td>
		<td><div class="line">{%= t("reviewer") %}</div></td>
		<td><div class="line">{%= t("fin_manager") %}</div></td>
		<td><div class="line">{%= t("general_manager") %}</div></td>
	</tr></table>
	{% } %}

	<table class="ft"><tr>
		<td style="width:50%;">{%= t("printed_by") %}: {%= esc((frappe.session && (frappe.session.user_fullname || frappe.session.user)) || "") %}</td>
		<td style="width:50%; text-align:{%= E %};">{%= t("printed_on") %}: <span class="ltr">{%= frappe.datetime.str_to_user(frappe.datetime.now_datetime()) %}</span></td>
	</tr></table>
</div>
